import threading
import uuid


class Queue:
    def __init__(self):
        self._lock = threading.Lock()
        self._jobs = {}   # job_id -> {state, expiry, worker, token}
        self._order = []  # list of job_ids in insertion order

    def add(self, job_id):
        with self._lock:
            if job_id not in self._jobs:
                self._jobs[job_id] = {'state': 'queued', 'expiry': None, 'worker': None, 'token': None}
                self._order.append(job_id)

    def claim(self, worker, now, ttl):
        with self._lock:
            if ttl <= 0:
                return None
            # Find first eligible job in insertion order
            for job_id in self._order:
                job = self._jobs[job_id]
                if job['state'] == 'queued':
                    # Queued jobs are always eligible
                    token = str(uuid.uuid4())
                    job['state'] = 'running'
                    job['expiry'] = now + ttl
                    job['worker'] = worker
                    job['token'] = token
                    return {'job_id': job_id, 'worker': worker, 'token': token}
                elif job['state'] == 'running':
                    # Running jobs eligible only if expired (expiry <= now)
                    if job['expiry'] is not None and job['expiry'] <= now:
                        token = str(uuid.uuid4())
                        job['expiry'] = now + ttl
                        job['worker'] = worker
                        job['token'] = token
                        return {'job_id': job_id, 'worker': worker, 'token': token}
            return None

    def renew(self, lease, now, ttl):
        with self._lock:
            job_id = lease['job_id']
            if job_id not in self._jobs:
                return False
            job = self._jobs[job_id]
            # Only exact current token and worker may act
            if job['token'] != lease['token'] or job['worker'] != lease['worker']:
                return False
            # Only non-expired running jobs may be renewed (expiry > now)
            if job['expiry'] is None or job['expiry'] <= now:
                return False
            job['expiry'] = now + ttl
            return True

    def complete(self, lease, now):
        with self._lock:
            job_id = lease['job_id']
            if job_id not in self._jobs:
                return False
            job = self._jobs[job_id]
            # Only exact current token and worker may act
            if job['token'] != lease['token'] or job['worker'] != lease['worker']:
                return False
            # Only non-expired running jobs may be completed (expiry > now)
            if job['expiry'] is None or job['expiry'] <= now:
                return False
            job['state'] = 'completed'
            return True
